      const t = getTheme();
      leftCol.innerHTML = '';
      rightCol.innerHTML = '';
      const first  = (getLayout() === 'cols') ? cfg.left  : [...cfg.left, ...cfg.right];
      const second = (getLayout() === 'cols') ? cfg.right : [];
      first .forEach(it => leftCol .appendChild(makeBtn(it.icon || it.id, it.link, t, it.fixedSrc, it)));
