    const re = new RegExp(labelRe.source + '\\s*(?:prize\\s+)?window[^0-9]{0,80}?(\\d{1,2}):(\\d{2}):(\\d{2})\\s*([AP]M)[^0-9]{0,40}?(\\d{1,2}):(\\d{2}):(\\d{2})\\s*([AP]M)', 'i');
