    const f = (v, u) => { const x = Math.floor(v * 10) / 10; return (x % 1 ? x.toFixed(1) : String(x)) + u; };
    const out = n >= 1e9 ? f(n / 1e9, 'B') : n >= 1e6 ? f(n / 1e6, 'M') : n >= 1e3 ? f(n / 1e3, 'K') : t;
