  const gmSet = (k, v) => { try { if (typeof GM_setValue === 'function') GM_setValue(k, v); else LSset(k, JSON.stringify(v)); } catch {} if (k === AP_KEY || k === AP_TAGS) LSset(k + '_bak', JSON.stringify(v)); };
