  const apLk = (url, txt) => `<a class="apLk" href="${esc(url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${esc(txt)}</a>`;
  const apPetLk = (n) => apLk(apPetUrl(n), n), apUserLk = (n) => apLk(apUserUrl(n), n);
