  function markProfDirty(first) {
    try { if (JSON.parse(LSget(DIRTY_KEY) || 'null')) return; } catch {}
    LSset(DIRTY_KEY, JSON.stringify({ t: Date.now() - (first ? 3000 : 0), n: first ? 2 : 0 }));
  }
